// CUDA backend using the driver API on the device's primary context, so OFX
// hosts that render with CUDA share our context. The driver library is opened
// at runtime; kernels come from the embedded nvcc fatbin (-fmad=false).
#include <cstdint>
#include <cstring>
#include <string>
#include <vector>

#include "gpu/device.h"

#if defined(_WIN32)
#ifndef NOMINMAX
#define NOMINMAX
#endif
#include <windows.h>
#define ADR_CU_API __stdcall
#else
#include <dlfcn.h>
#define ADR_CU_API
#endif

namespace adr {

// Generated by cmake/cuda_kernels.cmake.
const unsigned char* cuda_fatbin();
size_t cuda_fatbin_size();

namespace {

typedef int CUresult;
typedef int CUdevice;
typedef unsigned long long CUdeviceptr;
typedef struct CUctx_st* CUcontext;
typedef struct CUmod_st* CUmodule;
typedef struct CUfunc_st* CUfunction;
typedef struct CUstream_st* CUstream;
constexpr unsigned CU_STREAM_NON_BLOCKING = 1;

struct Api {
  CUresult(ADR_CU_API* Init)(unsigned);
  CUresult(ADR_CU_API* DeviceGetCount)(int*);
  CUresult(ADR_CU_API* DeviceGet)(CUdevice*, int);
  CUresult(ADR_CU_API* DeviceGetName)(char*, int, CUdevice);
  CUresult(ADR_CU_API* DevicePrimaryCtxRetain)(CUcontext*, CUdevice);
  CUresult(ADR_CU_API* DevicePrimaryCtxRelease)(CUdevice);
  CUresult(ADR_CU_API* CtxSetCurrent)(CUcontext);
  CUresult(ADR_CU_API* StreamCreate)(CUstream*, unsigned);
  CUresult(ADR_CU_API* StreamDestroy)(CUstream);
  CUresult(ADR_CU_API* StreamSynchronize)(CUstream);
  CUresult(ADR_CU_API* MemAlloc)(CUdeviceptr*, size_t);
  CUresult(ADR_CU_API* MemFree)(CUdeviceptr);
  CUresult(ADR_CU_API* MemcpyHtoDAsync)(CUdeviceptr, const void*, size_t, CUstream);
  CUresult(ADR_CU_API* MemcpyDtoHAsync)(void*, CUdeviceptr, size_t, CUstream);
  CUresult(ADR_CU_API* MemcpyDtoDAsync)(CUdeviceptr, CUdeviceptr, size_t, CUstream);
  CUresult(ADR_CU_API* MemsetD8Async)(CUdeviceptr, unsigned char, size_t, CUstream);
  CUresult(ADR_CU_API* ModuleLoadData)(CUmodule*, const void*);
  CUresult(ADR_CU_API* ModuleUnload)(CUmodule);
  CUresult(ADR_CU_API* ModuleGetFunction)(CUfunction*, CUmodule, const char*);
  CUresult(ADR_CU_API* LaunchKernel)(CUfunction, unsigned, unsigned, unsigned, unsigned, unsigned, unsigned, unsigned,
                                    CUstream, void**, void**);
  CUresult(ADR_CU_API* GetErrorString)(CUresult, const char**);
};

const Api& api() {
  static Api table;
  static bool loaded = false;
  static std::string failure;
  if (loaded) return table;
  if (!failure.empty()) throw Error(failure);
#if defined(_WIN32)
  HMODULE library = LoadLibraryA("nvcuda.dll");
  auto symbol = [&](const char* name) { return reinterpret_cast<void*>(GetProcAddress(library, name)); };
#else
  void* library = dlopen("libcuda.so.1", RTLD_NOW | RTLD_LOCAL);
  auto symbol = [&](const char* name) { return dlsym(library, name); };
#endif
  if (!library) {
    failure = "NVIDIA CUDA driver not found";
    throw Error(failure);
  }
  bool ok = true;
  auto bind = [&](auto& fn, const char* name) {
    void* address = symbol(name);
    if (!address) ok = false;
    std::memcpy(&fn, &address, sizeof(void*));
  };
  bind(table.Init, "cuInit");
  bind(table.DeviceGetCount, "cuDeviceGetCount");
  bind(table.DeviceGet, "cuDeviceGet");
  bind(table.DeviceGetName, "cuDeviceGetName");
  bind(table.DevicePrimaryCtxRetain, "cuDevicePrimaryCtxRetain");
  bind(table.DevicePrimaryCtxRelease, "cuDevicePrimaryCtxRelease_v2");
  bind(table.CtxSetCurrent, "cuCtxSetCurrent");
  bind(table.StreamCreate, "cuStreamCreate");
  bind(table.StreamDestroy, "cuStreamDestroy_v2");
  bind(table.StreamSynchronize, "cuStreamSynchronize");
  bind(table.MemAlloc, "cuMemAlloc_v2");
  bind(table.MemFree, "cuMemFree_v2");
  bind(table.MemcpyHtoDAsync, "cuMemcpyHtoDAsync_v2");
  bind(table.MemcpyDtoHAsync, "cuMemcpyDtoHAsync_v2");
  bind(table.MemcpyDtoDAsync, "cuMemcpyDtoDAsync_v2");
  bind(table.MemsetD8Async, "cuMemsetD8Async");
  bind(table.ModuleLoadData, "cuModuleLoadData");
  bind(table.ModuleUnload, "cuModuleUnload");
  bind(table.ModuleGetFunction, "cuModuleGetFunction");
  bind(table.LaunchKernel, "cuLaunchKernel");
  bind(table.GetErrorString, "cuGetErrorString");
  if (!ok) {
    failure = "CUDA driver entry points missing";
    throw Error(failure);
  }
  if (table.Init(0) != 0) {
    failure = "CUDA driver initialisation failed";
    throw Error(failure);
  }
  loaded = true;
  return table;
}

void check(CUresult status, const char* what) {
  if (status == 0) return;
  const char* text = nullptr;
  api().GetErrorString(status, &text);
  throw Error(std::string("CUDA ") + what + " failed: " + (text ? text : std::to_string(status)));
}

class CudaDevice final : public Device {
 public:
  explicit CudaDevice(int index) {
    const Api& cu = api();
    int count = 0;
    check(cu.DeviceGetCount(&count), "device query");
    if (index < 0 || index >= count) throw Error("CUDA device index out of range");
    check(cu.DeviceGet(&device_, index), "device query");
    char name[256] = {};
    cu.DeviceGetName(name, sizeof(name), device_);
    name_ = name;
    check(cu.DevicePrimaryCtxRetain(&context_, device_), "context");
    current();
    check(cu.StreamCreate(&stream_, CU_STREAM_NON_BLOCKING), "stream creation");
    check(cu.ModuleLoadData(&module_, cuda_fatbin()), "kernel module load");
  }

  ~CudaDevice() override {
    try {
      synchronize();
    } catch (...) {
    }
    current();
    release_resources();
    const Api& cu = api();
    if (module_) cu.ModuleUnload(module_);
    if (stream_) cu.StreamDestroy(stream_);
    cu.DevicePrimaryCtxRelease(device_);
  }

  std::string name() const override { return name_; }
  std::string backend() const override { return "cuda"; }
  void* native_queue() const override { return stream_; }

  void upload(const Buffer& dst, const void* src, size_t bytes, size_t offset) override {
    if (!bytes) return;
    current();
    // Pageable source: the driver stages the copy before returning, and the
    // stream orders it after earlier readers of a recycled destination.
    check(api().MemcpyHtoDAsync(ptr(dst) + offset, src, bytes, stream_), "upload");
  }

  void download(void* dst, const Buffer& src, size_t bytes, size_t offset) override {
    if (!bytes) return;
    current();
    check(api().MemcpyDtoHAsync(dst, ptr(src) + offset, bytes, stream_), "download");
    check(api().StreamSynchronize(stream_), "download");
  }

  void fill(const Buffer& dst, uint8_t value, size_t bytes, size_t offset) override {
    if (!bytes) return;
    current();
    check(api().MemsetD8Async(ptr(dst) + offset, value, bytes, stream_), "fill");
  }

  void copy(const Buffer& dst, const Buffer& src, size_t bytes, size_t dst_offset, size_t src_offset) override {
    if (!bytes) return;
    current();
    check(api().MemcpyDtoDAsync(ptr(dst) + dst_offset, ptr(src) + src_offset, bytes, stream_), "copy");
  }

  void launch(KernelHandle* kernel, Dim3 threads, Dim3 group, std::initializer_list<const Buffer*> buffers,
              const void* params, size_t params_bytes) override {
    if (threads.x <= 0 || threads.y <= 0 || threads.z <= 0) return;
    current();
    CUdeviceptr pointers[32];
    void* args[33];
    size_t n = 0;
    for (const Buffer* b : buffers) {
      if (n >= 32) throw Error("Too many kernel buffers");
      pointers[n] = (b && *b) ? ptr(*b) : 0;
      args[n] = &pointers[n];
      ++n;
    }
    if (params_bytes) args[n++] = const_cast<void*>(params);
    CUresult status = api().LaunchKernel(static_cast<CUfunction>(kernel->native), (threads.x + group.x - 1) / group.x,
                                         (threads.y + group.y - 1) / group.y, (threads.z + group.z - 1) / group.z,
                                         group.x, group.y, group.z, 0, stream_, args, nullptr);
    if (status) check(status, ("launch of " + kernel->name).c_str());
  }

  void flush() override {}
  void synchronize() override {
    current();
    check(api().StreamSynchronize(stream_), "synchronize");
  }

 protected:
  BufferHandle allocate_native(size_t bytes) override {
    current();
    CUdeviceptr p = 0;
    check(api().MemAlloc(&p, bytes), "allocation");
    BufferHandle handle;
    handle.native = reinterpret_cast<void*>(static_cast<uintptr_t>(p));
    handle.bytes = bytes;
    return handle;
  }

  void release_native(BufferHandle handle) override {
    current();
    api().MemFree(static_cast<CUdeviceptr>(reinterpret_cast<uintptr_t>(handle.native)));
  }

  void* load_kernel(const std::string& name) override {
    current();
    CUfunction f = nullptr;
    if (api().ModuleGetFunction(&f, module_, name.c_str()) != 0) return nullptr;
    return f;
  }

 private:
  static CUdeviceptr ptr(const Buffer& b) { return static_cast<CUdeviceptr>(reinterpret_cast<uintptr_t>(b.native())); }
  void current() { api().CtxSetCurrent(context_); }

  CUdevice device_ = 0;
  CUcontext context_ = nullptr;
  CUstream stream_ = nullptr;
  CUmodule module_ = nullptr;
  std::string name_;
};

}  // namespace

std::unique_ptr<Device> create_cuda_device(int index) { return std::make_unique<CudaDevice>(index); }

}  // namespace adr
